def szukaj_liniowo(dane, cel):
    for i, wartosc in enumerate(dane):
        if wartosc == cel:
            return i
    return -1

def szukaj_binarnie(dane, cel):
    lewy, prawy = 0, len(dane) - 1
    while lewy <= prawy:
        srodek = (lewy + prawy) // 2
        if dane[srodek] == cel:
            return srodek
        if dane[srodek] < cel:
            lewy = srodek + 1     # odrzuć lewą połowę razem ze środkiem
        else:
            prawy = srodek - 1    # odrzuć prawą połowę razem ze środkiem
    return -1
